setTimeout(() => console.log('Hello, World!'), 0);

// с помощью хеш map можно кэшировать результаты вычислений для каждого n, чтобы избежать повторных вычислений и значительно улучшить производительность.
// тоесть в кеше мы сохраняем уже вычисленные значения для каждого n, и при последующих вызовах функции fib с тем же n мы можем просто возвращать результат из кеша, не выполняя рекурсивные вызовы.
// Это позволяет нам эффективно вычислять большие числа Фибоначчи без риска переполнения стека вызовов и значительно улучшает производительность.
const cache = new Map();

function fib(n) {
  return new Promise((resolve, reject) => {
    if (n === 0 || n === 1) {
      return resolve(n);
    }

    // проверяем, есть ли уже результат для текущего n в кэше.
    // Если да, то возвращаем его сразу, не выполняя рекурсивные вызовы.
    if (cache.has(n)) {
      return resolve(cache.get(n));
    }

    // благодаря setImmediate мы не блокируем основной поток выполнения, позволяя другим задачам выполняться, пока мы асинхронно вычисляем результат для текущего n.
    setImmediate(() =>
      fib(n - 1).then((fib1) => {
        fib(n - 2).then((fib2) => {
          cache.set(n, fib1 + fib2); // сохраняем результат в кэше перед возвратом
          resolve(fib1 + fib2);
        });
      }),
    );
  });
}

fib(1000).then((result) => console.log(`${result}`));

/*
  ------------------------------------------------------------
  ПОДРОБНЫЙ РАЗБОР КОДА
  ------------------------------------------------------------

  1. Что делает программа

  Этот код вычисляет число Фибоначчи для n = 1000.

  Последовательность Фибоначчи строится так:

    fib(0) = 0
    fib(1) = 1
    fib(2) = fib(1) + fib(0) = 1
    fib(3) = fib(2) + fib(1) = 2
    fib(4) = fib(3) + fib(2) = 3
    ...

  То есть каждое следующее число равно сумме двух предыдущих.

  Здесь задача решается не просто рекурсией, а с тремя важными идеями:

    1. через Promise:
       функция fib возвращает промис, а не обычное число;

    2. через setImmediate:
       тяжелая работа разбивается на отдельные шаги и отдается обратно
       циклу событий Node.js, чтобы не "залипать" надолго в одном
       непрерывном синхронном вычислении;

    3. через Map-кэш:
       уже найденные значения запоминаются, чтобы не считать их повторно.


  2. Первая строка

    setTimeout(() => console.log('Hello, World!'), 0);

  Эта строка ставит задачу в очередь таймеров:

    "как только дойдет очередь, выведи Hello, World!"

  Задержка 0 не означает "прямо сейчас".
  Это означает:

    "выполни на ближайшей итерации event loop, когда будет можно"

  Зачем это здесь:

    строка нужна как наглядная проверка, блокируем ли мы event loop или нет.

  Если бы вычисление Фибоначчи было полностью тяжелым и синхронным,
  то вывод "Hello, World!" мог бы заметно задержаться.


  3. Кэш

    const cache = new Map();

  Map - это структура данных "ключ -> значение".

  В этом случае:

    ключ    = n
    значение = fib(n)

  Пример того, что может лежать в cache после вычислений:

    2   -> 1
    3   -> 2
    4   -> 3
    5   -> 5
    6   -> 8
    ...

  Зачем нужен кэш:

    в обычной рекурсии одни и те же значения вычисляются очень много раз.

  Например, для fib(6):

                  fib(6)
                 /      \
             fib(5)    fib(4)
             /   \      /   \
         fib(4) fib(3) fib(3) fib(2)

  Здесь видно, что:

    fib(4) считается несколько раз
    fib(3) считается несколько раз
    fib(2) тоже может повторяться

  Без кэша дерево вызовов разрастается очень быстро.
  С кэшем:

    один раз посчитали fib(4)
    сохранили его в Map
    все следующие обращения просто берут готовое значение


  4. Заголовок функции

    function fib(n) {
      return new Promise((resolve, reject) => {

  Это означает:

    функция fib не возвращает число сразу,
    она возвращает Promise, который когда-то позже будет завершен.

  Идея такая:

    fib(1000)
      -> "я пока не готов дать результат немедленно,
          но обещаю отдать его позже через resolve(...)"

  Важно:

    reject здесь объявлен, но в текущем коде не используется.
    То есть ошибок функция специально не обрабатывает и не пробрасывает.


  5. Базовый случай рекурсии

    if (n === 0 || n === 1) {
      return resolve(n);
    }

  Это остановка рекурсии.

  Если не сделать базовый случай, функция будет вызывать сама себя бесконечно:

    fib(5)
    -> fib(4), fib(3)
    -> fib(3), fib(2), fib(2), fib(1)
    -> ...

  Базовый случай говорит:

    если n равно 0, ответ 0
    если n равно 1, ответ 1

  Здесь мы сразу завершаем Promise:

    resolve(n)

  То есть для самых маленьких значений ждать ничего не нужно.


  6. Проверка кэша

    if (cache.has(n)) {
      return resolve(cache.get(n));
    }

  Логика:

    "если мы уже раньше считали fib(n),
     то не надо считать снова - просто вернем готовый ответ"

  Разбор по шагам:

    cache.has(n)
      проверяет, есть ли в Map значение для текущего n

    cache.get(n)
      достает это значение

    resolve(...)
      завершает Promise найденным числом

  Это главный источник ускорения в программе.


  7. Зачем нужен setImmediate

    setImmediate(() =>
      ...
    );

  setImmediate в Node.js откладывает выполнение функции на следующую
  подходящую фазу event loop.

  Простая идея:

    вместо того чтобы прямо сейчас глубоко проваливаться в рекурсию,
    мы говорим Node.js:

      "выполни этот следующий шаг чуть позже"

  Что это дает:

    1. стек вызовов не растет как при чистой синхронной рекурсии;
    2. event loop получает шанс обработать другие отложенные задачи;
    3. программа ведет себя более дружелюбно по отношению к остальному коду.

  Упрощенная схема:

    Без setImmediate:

      fib(1000)
        -> fib(999)
          -> fib(998)
            -> fib(997)
              -> ...

      Все это идет сразу в одном длинном синхронном каскаде.

    С setImmediate:

      fib(1000)
        -> "запланировать следующий шаг"
        -> отдать управление event loop
        -> позже выполнить следующий шаг
        -> снова запланировать следующий шаг
        -> снова отдать управление event loop

  То есть вычисление как будто режется на кусочки.

  Важно понимать:

    setImmediate не делает вычисление "магически бесплатным".
    Он не ускоряет математику сам по себе.

  Он меняет характер выполнения:

    из непрерывного и потенциально блокирующего
    в более кооперативное и отложенное.


  8. Основная логика вычисления

    fib(n - 1).then((fib1) => {
      fib(n - 2).then((fib2) => {
        cache.set(n, fib1 + fib2);
        resolve(fib1 + fib2);
      });
    })

  Что здесь происходит:

    1. сначала считаем fib(n - 1)
    2. когда он готов, считаем fib(n - 2)
    3. складываем результаты
    4. сохраняем сумму в кэш
    5. возвращаем итог через resolve

  Обратите внимание:

    в этой версии вычисления идут последовательно, а не параллельно.

  То есть сначала:

    fib(n - 1)

  и только потом:

    fib(n - 2)

  Почему это здесь нормально и даже полезно:

    пока считается fib(n - 1), рекурсивно заполняется кэш для меньших n.
    Поэтому к моменту вызова fib(n - 2) это значение очень часто уже лежит в cache.

  Пример для fib(5):

    fib(5)
      -> ждем fib(4)
         fib(4)
           -> ждем fib(3)
              fib(3)
                -> ждем fib(2)
                   fib(2)
                     -> fib(1) = 1
                     -> fib(0) = 0
                     -> cache[2] = 1
                -> fib(1) = 1
                -> cache[3] = 2
           -> fib(2) уже есть в cache
           -> cache[4] = 3
      -> fib(3) уже есть в cache
      -> cache[5] = 5

  Схема того же процесса:

    fib(5)
      |
      +-- fib(4)
      |     |
      |     +-- fib(3)
      |     |     |
      |     |     +-- fib(2)
      |     |     |     |
      |     |     |     +-- fib(1) = 1
      |     |     |     +-- fib(0) = 0
      |     |     |     +-- cache[2] = 1
      |     |     |
      |     |     +-- fib(1) = 1
      |     |     +-- cache[3] = 2
      |     |
      |     +-- fib(2) берем из cache
      |     +-- cache[4] = 3
      |
      +-- fib(3) берем из cache
      +-- cache[5] = 5


  9. Почему cache.set вызывается перед resolve

    cache.set(n, fib1 + fib2);
    resolve(fib1 + fib2);

  Сначала результат записывается в кэш, потом возвращается наружу.

  Это важно, потому что:

    как только текущий fib(n) завершился,
    другие части программы уже могут попросить это же значение.

  Если сначала вернуть результат, а потом почему-то не успеть записать его в cache,
  можно потерять часть пользы от мемоизации.

  Здесь порядок правильный и логичный:

    1. посчитали
    2. сохранили
    3. отдали


  10. Последняя строка

    fib(1000).then((result) => console.log(`${result}`));

  Это означает:

    "запусти вычисление fib(1000)
     и когда оно завершится, выведи результат в консоль"

  Почему используется .then(...):

    потому что fib возвращает Promise, а не число напрямую.

  То есть нельзя сделать так:

    const x = fib(1000);
    console.log(x);

  В таком случае в x будет Promise, а не итоговое число.

  Нужно либо:

    fib(1000).then(...)

  либо:

    const result = await fib(1000);


  11. Как это выглядит с точки зрения event loop

  Очень грубо и упрощенно:

    СТАРТ ПРОГРАММЫ
      |
      +-- ставим setTimeout(..., 0)
      +-- создаем cache
      +-- вызываем fib(1000)
            |
            +-- Promise создается сразу
            +-- базовый случай не подходит
            +-- в cache еще нет 1000
            +-- ставим setImmediate для дальнейшего шага
      +-- основной код файла закончился
      |
      V
    EVENT LOOP
      |
      +-- выполняет очереди отложенных задач
      +-- когда приходит время, запускает callback setTimeout
      +-- когда приходит время, запускает callback setImmediate
      +-- callback продолжает цепочку fib(...)
      +-- по мере завершения промисов вызываются .then(...)
      +-- в cache постепенно копятся значения
      +-- в конце resolve для fib(1000)
      +-- console.log(result)

  Важная аккуратность:

    если сравнивать setTimeout(..., 0) и setImmediate(...) в Node.js,
    порядок их срабатывания из верхнего уровня файла не стоит считать
    абсолютно гарантированным во всех ситуациях.

  То есть:

    нельзя строить критическую бизнес-логику на ожидании
    "таймер 0 всегда раньше setImmediate" или наоборот.


  12. Почему такой подход лучше обычной наивной рекурсии

  Наивная синхронная версия обычно выглядит так:

    function fib(n) {
      if (n === 0 || n === 1) return n;
      return fib(n - 1) + fib(n - 2);
    }

  Ее проблемы:

    1. очень много повторных вычислений;
    2. резкий рост времени работы;
    3. глубокая рекурсия может быть опасна для стека вызовов;
    4. пока функция считает, поток выполнения занят.

  Текущая версия улучшает ситуацию так:

    1. cache убирает повторные вычисления;
    2. setImmediate помогает не держать длинную синхронную рекурсию;
    3. Promise-цепочки позволяют работать в асинхронном стиле.


  13. Сложность

  Если смотреть концептуально:

    без кэша:
      время растет очень быстро, почти экспоненциально

    с кэшем:
      количество уникальных подзадач становится примерно O(n)

  Но есть важная оговорка:

    в реальности здесь есть накладные расходы на:
      - создание множества Promise
      - планирование через setImmediate
      - работу callback-ов

  Поэтому:

    алгоритмически стало намного лучше,
    но practically это все равно не самый дешевый способ вычислять большие
    числа Фибоначчи в Node.js.


  14. Что особенно важно понять по смыслу

  Этот код демонстрирует сразу несколько идей:

    1. рекурсия
    2. базовый случай
    3. мемоизация (кэширование результатов)
    4. асинхронное выполнение через Promise
    5. неблокирующее планирование через setImmediate
    6. взаимодействие с event loop

  То есть это не просто "как найти fib(1000)".
  Это пример того, как тяжелую рекурсивную задачу можно переписать так,
  чтобы:

    - меньше дублировать работу
    - аккуратнее вести себя по отношению к event loop
    - наглядно увидеть асинхронный стиль в Node.js


  15. Краткая супер-схема всего алгоритма

    fib(n)
      |
      +-- если n = 0 или 1
      |     |
      |     +-- сразу resolve(n)
      |
      +-- если n есть в cache
      |     |
      |     +-- сразу resolve(cache[n])
      |
      +-- иначе
            |
            +-- setImmediate(...)
                  |
                  +-- дождаться fib(n - 1)
                  +-- дождаться fib(n - 2)
                  +-- sum = fib1 + fib2
                  +-- cache[n] = sum
                  +-- resolve(sum)


  16. Идея в одной фразе

  Код считает числа Фибоначчи асинхронно, разбивает рекурсивные шаги через
  setImmediate и ускоряет вычисление за счет кэширования уже найденных
  значений в Map.
*/
